// Repository: CheckinRepository
// Responsável por: criar check-in, escutar resultado da IA via Realtime

import { supabase } from '../../lib/supabase'
import type {
  Checkin,
  CheckinCreateInput,
  DayStateLabel,
  FocusIntensity,
  TccTechnique,
} from '../entities/checkin'

export interface CheckinCreateResult {
  checkin: Checkin
  status: 'processing' | 'complete'
}

// Cria check-in e retorna imediatamente (IA processa em background)
export async function createCheckin(
  input: CheckinCreateInput
): Promise<CheckinCreateResult> {
  const { data, error } = await supabase.functions.invoke('checkin-create', {
    body: input,
  })
  if (error) throw new Error(error.message)
  return {
    checkin: parseCheckin(data.checkin),
    status: data.status,
  }
}

// Escuta Realtime até a IA preencher o estado — chama onUpdate quando pronto
export function subscribeToCheckinAi(
  checkinId: string,
  onUpdate: (checkin: Checkin) => void
) {
  const channel = (supabase as any)
    .channel(`checkin-ai:${checkinId}`)
    .on(
      'postgres_changes',
      {
        event:  'UPDATE',
        schema: 'public',
        table:  'daily_checkins',
        filter: `id=eq.${checkinId}`,
      },
      (payload: any) => {
        const row = payload.new
        // Só notifica quando a IA terminar (day_state_label preenchido)
        if (row.day_state_label) {
          onUpdate(parseCheckin(row))
          channel.unsubscribe()
        }
      }
    )
    .subscribe()

  // Retorna função de cleanup para usar em useEffect
  return () => channel.unsubscribe()
}

// Busca histórico de check-ins dos últimos N dias
export async function fetchCheckinHistory(days = 7): Promise<Checkin[]> {
  const weekStart = new Date()
  weekStart.setDate(weekStart.getDate() - days)

  const { data, error } = await supabase
    .from('daily_checkins')
    .select('*')
    .gte('checkin_date', weekStart.toISOString().split('T')[0])
    .order('checkin_date', { ascending: false })
    .order('created_at', { ascending: false })

  if (error) throw new Error(error.message)
  return (data ?? []).map(parseCheckin)
}

// Mapeia snake_case do banco → camelCase da entity
function parseCheckin(row: Record<string, any>): Checkin {
  return {
    id:               row.id,
    date:             row.checkin_date,
    period:           row.period,
    moodScore:        row.mood_score,
    energyScore:      row.energy_score,
    clarityScore:     row.mental_clarity,
    irritabilityScore: row.irritability,
    physicalScore:    row.physical_score,
    socialScore:      row.social_score,
    note:             row.note ?? undefined,
    stateLabel:       row.state_summary ?? undefined,
    stateLabelType:   (row.day_state_label as DayStateLabel) ?? undefined,
    tccSuggestion:    row.tcc_suggestion ?? undefined,
    tccTechnique:     (row.tcc_technique as TccTechnique) ?? undefined,
    energyStateInternal: row.day_state_label ? {
      analysis:           row.state_summary ?? '',
      recommendations:    row.ai_recommendations ?? [],
      suggestedIntensity: (row.suggested_focus_level as FocusIntensity) ?? 'M',
    } : undefined,
  }
}

import { createClient } from '@supabase/supabase-js';
import AsyncStorage from '@react-native-async-storage/async-storage';

const supabaseUrl = process.env.EXPO_PUBLIC_SUPABASE_URL;
const supabaseAnonKey = process.env.EXPO_PUBLIC_SUPABASE_ANON_KEY;

// Inicialização segura para evitar crash fatal no APK caso as env vars faltem no build
export const supabase = (supabaseUrl && supabaseAnonKey)
  ? createClient(supabaseUrl, supabaseAnonKey, {
      auth: {
        storage: AsyncStorage,
        autoRefreshToken: true,
        persistSession: true,
        detectSessionInUrl: false,
      },
    })
  : new Proxy({} as any, {
      get: (target, prop) => {
        console.warn(`Supabase: Tentativa de acessar "${String(prop)}" sem env vars configuradas.`);
        // Retorna mocks mínimos para não quebrar o fluxo de renderização inicial
        if (prop === 'auth') {
          return {
            getSession: async () => ({ data: { session: null }, error: null }),
            onAuthStateChange: () => ({ data: { subscription: { unsubscribe: () => {} } } }),
            signOut: async () => ({ error: null }),
          };
        }
        return () => ({
          from: () => ({ select: () => ({ eq: () => ({ maybeSingle: async () => ({ data: null, error: null }) }) }) }),
        });
      }
    });

import React from 'react';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { View } from 'react-native';
import { ActivityIndicator } from 'react-native-paper';
import DailySummaryScreen from '../screens/DailySummaryScreen';
import CheckinScreen from '../screens/CheckinScreen';
import CheckInResultScreen from '../screens/CheckInResultScreen';
import AuthScreen from '../screens/AuthScreen';
import WebAppScreen from '../screens/WebAppScreen';
import ForgotPasswordScreen from '../screens/ForgotPasswordScreen';
import HrvTestScreen from '../screens/HrvTestScreen';
import HrvResultScreen from '../screens/HrvResultScreen';
import CycleCalendarScreen from '../screens/CycleCalendarScreen';
import DailyAgendaScreen from '../screens/DailyAgendaScreen';
import EnergyMapScreen from '../screens/EnergyMapScreen';
import PlansScreen from '../screens/PlansScreen';
import PaymentSuccessScreen from '../screens/PaymentSuccessScreen';
import GoogleCalendarScreen from '../screens/GoogleCalendarScreen';
import JournalChatScreen from '../screens/JournalChatScreen';
import HabitsScreen from '../screens/HabitsScreen';
import { useAuthStore } from '../providers/auth_store';
import { appColors } from '../theme/appTheme';

const Stack = createNativeStackNavigator();

/**
 * RootStackNavigator: Gerencia a navegação global do App.
 * Focado no WebShell para paridade total com o Web App.
 */
export default function RootStackNavigator() {
  const { initialized, isLoading } = useAuthStore();

  if (!initialized && isLoading) {
    return (
      <View
        style={{
          flex: 1,
          alignItems: 'center',
          justifyContent: 'center',
          backgroundColor: appColors.background,
        }}
      >
        <ActivityIndicator animating size="large" color={appColors.primary} />
      </View>
    );
  }

  return (
    <Stack.Navigator
      screenOptions={{
        headerShown: false,
        contentStyle: {
          backgroundColor: appColors.background,
        },
      }}
    >
      <Stack.Screen name="WebShell" component={WebAppScreen} />
      <Stack.Screen
        name="ForgotPassword"
        component={ForgotPasswordScreen}
        options={{
          animation: 'slide_from_right',
        }}
      />
    </Stack.Navigator>
  );
}

import { create } from 'zustand';
import { makeRedirectUri } from 'expo-auth-session';
import * as WebBrowser from 'expo-web-browser';

import { supabase } from '../../lib/supabase';
import { getSessionUserId, type SessionSnapshot } from './auth_session';

interface AuthState {
  userId: string | null;
  fullName: string | null;
  onboardingDone: boolean;
  isLoading: boolean;
  initialized: boolean;
  error: string | null;
  infoMessage: string | null;
  initialize: () => Promise<void>;
  refresh: () => Promise<void>;
  signIn: (email: string, password: string) => Promise<boolean>;
  signInWithGoogle: () => Promise<boolean>;
  signUp: (input: { fullName: string; email: string; password: string }) => Promise<boolean>;
  signOut: () => Promise<void>;
  clearMessages: () => void;
}

let authSubscriptionInitialized = false;
WebBrowser.maybeCompleteAuthSession();

async function fetchProfile(userId: string): Promise<{ fullName: string | null; onboardingDone: boolean }> {
  const { data, error } = await supabase
    .from('profiles')
    .select('full_name, onboarding_done')
    .eq('id', userId)
    .maybeSingle();

  if (error) {
    throw error;
  }

  return {
    fullName: data?.full_name ?? null,
    onboardingDone: data?.onboarding_done ?? false,
  };
}

async function readSessionUserId(): Promise<string | null> {
  const { data, error } = await supabase.auth.getSession();

  if (error) {
    throw error;
  }

  return getSessionUserId(data as SessionSnapshot);
}

async function syncAuthState(
  set: (partial: Partial<AuthState>) => void,
  sessionUserId: string | null,
) {
  if (!sessionUserId) {
    set({
      userId: null,
      fullName: null,
      onboardingDone: false,
      initialized: true,
      isLoading: false,
    });
    return;
  }

  const profile = await fetchProfile(sessionUserId);

  set({
    userId: sessionUserId,
    fullName: profile.fullName,
    onboardingDone: profile.onboardingDone,
    initialized: true,
    isLoading: false,
  });
}

export const useAuthStore = create<AuthState>((set) => ({
  userId: null,
  fullName: null,
  onboardingDone: false,
  isLoading: false,
  initialized: false,
  error: null,
  infoMessage: null,

  async initialize() {
    if (!authSubscriptionInitialized) {
      supabase.auth.onAuthStateChange((_event: any, session: any) => {
        void syncAuthState(set, session?.user?.id ?? null).catch((error) => {
          set({
            initialized: true,
            isLoading: false,
            error: error instanceof Error ? error.message : 'Falha ao sincronizar sessão.',
          });
        });
      });
      authSubscriptionInitialized = true;
    }

    set({ isLoading: true, error: null, infoMessage: null });

    try {
      const userId = await readSessionUserId();
      await syncAuthState(set, userId);
    } catch (error) {
      set({
        isLoading: false,
        initialized: true,
        error: error instanceof Error ? error.message : 'Falha ao carregar sessão.',
      });
    }
  },

  async refresh() {
    set({ isLoading: true, error: null });

    try {
      const userId = await readSessionUserId();
      await syncAuthState(set, userId);
    } catch (error) {
      set({
        isLoading: false,
        error: error instanceof Error ? error.message : 'Falha ao atualizar sessão.',
      });
    }
  },

  async signIn(email, password) {
    set({ isLoading: true, error: null, infoMessage: null });

    try {
      const { data, error } = await supabase.auth.signInWithPassword({
        email: email.trim(),
        password,
      });

      if (error) {
        throw error;
      }

      await syncAuthState(set, data.user?.id ?? null);
      return true;
    } catch (error) {
      set({
        isLoading: false,
        error: error instanceof Error ? error.message : 'Falha ao entrar.',
      });
      return false;
    }
  },

  async signInWithGoogle() {
    set({ isLoading: true, error: null, infoMessage: null });

    try {
      const redirectTo = makeRedirectUri({
        scheme: 'airia',
        path: 'auth/callback',
      });

      const { data, error } = await supabase.auth.signInWithOAuth({
        provider: 'google',
        options: {
          redirectTo,
          skipBrowserRedirect: true,
          queryParams: {
            access_type: 'offline',
            prompt: 'consent',
          },
        },
      });

      if (error) {
        throw error;
      }

      if (!data?.url) {
        throw new Error('Nao foi possivel iniciar o login com Google.');
      }

      const result = await WebBrowser.openAuthSessionAsync(data.url, redirectTo);

      if (result.type !== 'success' || !result.url) {
        set({ isLoading: false });
        return false;
      }

      const callbackUrl = new URL(result.url);
      const code = callbackUrl.searchParams.get('code');

      if (!code) {
        throw new Error('Google nao retornou o codigo de autenticacao.');
      }

      const { data: sessionData, error: exchangeError } = await supabase.auth.exchangeCodeForSession(code);

      if (exchangeError) {
        throw exchangeError;
      }

      await syncAuthState(set, sessionData.session?.user?.id ?? sessionData.user?.id ?? null);
      return true;
    } catch (error) {
      set({
        isLoading: false,
        error: error instanceof Error ? error.message : 'Falha ao entrar com Google.',
      });
      return false;
    }
  },

  async signUp({ fullName, email, password }) {
    set({ isLoading: true, error: null, infoMessage: null });

    try {
      const { data, error } = await supabase.auth.signUp({
        email: email.trim(),
        password,
        options: {
          data: {
            full_name: fullName.trim(),
          },
        },
      });

      if (error) {
        throw error;
      }

      if (!data.session) {
        set({
          isLoading: false,
          initialized: true,
          infoMessage: 'Conta criada. Verifique seu email para confirmar o acesso.',
        });
        return true;
      }

      await syncAuthState(set, data.user?.id ?? null);
      return true;
    } catch (error) {
      set({
        isLoading: false,
        error: error instanceof Error ? error.message : 'Falha ao criar conta.',
      });
      return false;
    }
  },

  async signOut() {
    set({ isLoading: true, error: null });

    try {
      const { error } = await supabase.auth.signOut();

      if (error) {
        throw error;
      }

      set({
        userId: null,
        fullName: null,
        onboardingDone: false,
        isLoading: false,
        initialized: true,
      });
    } catch (error) {
      set({
        isLoading: false,
        error: error instanceof Error ? error.message : 'Falha ao encerrar sessão.',
      });
    }
  },

  clearMessages() {
    set({
      error: null,
      infoMessage: null,
    });
  },
}));

import { create } from 'zustand';
import { AIService, CheckinResponse } from '../../services/ai_service';
import api from '../../services/api_service';

/**
 * Entidade de dados para o formulário de Check-in (Clean Architecture)
 */
export interface CheckinFormData {
  userId: string;
  localDate: string;
  moodScore: number;
  energyScore: number;
  clarityScore?: number | null;
  irritabilityScore?: number | null;
  physicalScore?: number | null;
  socialScore?: number | null;
  sleepScore?: number | null;
  sleepHours?: number | null;
  menstrualPhase?: string;
  cycleDay?: number;
  physicalSymptoms?: string[];
  isFlowing?: boolean;
  flowDay?: number;
  flowIntensity?: 'leve' | 'moderado' | 'intenso';
  symptomLevels?: {
    colica?: 1 | 2 | 3;
    dorCabeca?: 1 | 2 | 3;
  };
  note?: string;
}

/**
 * Interface de Estado (State) equivalente ao CheckinState do Flutter
 */
interface CheckinState {
  isLoading: boolean;
  todayCheckin: CheckinResponse | null;
  recentCheckins: CheckinResponse[];
  error: string | null;

  // Actions (Notifiers)
  submitCheckin: (data: CheckinFormData) => Promise<void>;
  loadRecentCheckins: (userId: string, days?: number) => Promise<void>;
  clearError: () => void;
}

/**
 * Zustand Store: O equivalente ao StateNotifierProvider do Riverpod.
 * Gerencia o estado global do Check-in no Mobile.
 */
export const useCheckinStore = create<CheckinState>((set, get) => ({
  isLoading: false,
  todayCheckin: null,
  recentCheckins: [],
  error: null,

  /**
   * Submete o Check-in e atualiza o estado com o resultado da IA.
   */
  submitCheckin: async (data: CheckinFormData) => {
    set({ isLoading: true, error: null });
    try {
      // Chamada via AIService (Repository Pattern)
      const result = await AIService.submitCheckin(data);

      set({ 
        isLoading: false, 
        todayCheckin: result 
      });

      // Aqui poderíamos disparar a navegação para a tela de resultado
    } catch (err: any) {
      set({ 
        isLoading: false, 
        error: err.message || 'Falha ao processar check-in' 
      });
    }
  },

  /**
   * Carrega os check-ins recentes do backend (GET /api/checkins?userId=&days=)
   */
  loadRecentCheckins: async (userId: string, days = 7) => {
    set({ isLoading: true, error: null });
    try {
      const response = await api.get<CheckinResponse[]>('/api/checkins', {
        params: { userId, days },
      });
      set({ recentCheckins: response.data, isLoading: false });
    } catch (err: any) {
      set({ isLoading: false, error: err.message });
    }
  },

  clearError: () => set({ error: null }),
}));

import { create } from 'zustand';
import { supabase } from '../../lib/supabase';

export interface Habit {
  id: string;
  title: string;
  description?: string;
  category: string;
  icon?: string;
  frequency: 'daily' | 'weekly' | 'monthly';
  targetDays: number[];
  timeOfDay?: string;
  streakCount: number;
  bestStreak: number;
  totalCompletions: number;
  completions?: HabitCompletion[];
}

export interface HabitCompletion {
  id: string;
  habitId: string;
  date: string;
  completedAt?: string;
}

interface HabitState {
  habits: Habit[];
  isLoading: boolean;
  error: string | null;

  fetchHabits: (userId: string, date: string) => Promise<void>;
  toggleHabit: (userId: string, habitId: string, date: string) => Promise<void>;
  addHabit: (userId: string, habit: Partial<Habit>) => Promise<void>;
}

export const useHabitStore = create<HabitState>((set, get) => ({
  habits: [],
  isLoading: false,
  error: null,

  fetchHabits: async (userId, date) => {
    set({ isLoading: true, error: null });
    try {
      const { data: { session } } = await supabase.auth.getSession();
      if (!session) throw new Error('No session');

      const response = await fetch(`${process.env.EXPO_PUBLIC_API_URL}/api/habits?date=${date}`, {
        headers: {
          Authorization: `Bearer ${session.access_token}`,
        },
      });

      if (!response.ok) throw new Error('Failed to fetch habits');
      const habits = await response.json();
      set({ habits, isLoading: false });
    } catch (err: any) {
      set({ error: err.message, isLoading: false });
    }
  },

  toggleHabit: async (userId, habitId, date) => {
    try {
      const { data: { session } } = await supabase.auth.getSession();
      if (!session) throw new Error('No session');

      const response = await fetch(`${process.env.EXPO_PUBLIC_API_URL}/api/habits/${habitId}/toggle`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${session.access_token}`,
        },
        body: JSON.stringify({ date }),
      });

      if (!response.ok) throw new Error('Failed to toggle habit');

      // Atualiza o estado local para refletir a mudança imediatamente
      const updatedHabit = await response.json();
      set((state) => ({
        habits: state.habits.map((h) => (h.id === habitId ? updatedHabit : h)),
      }));
    } catch (err: any) {
      set({ error: err.message });
    }
  },

  addHabit: async (userId, habitData) => {
    set({ isLoading: true, error: null });
    try {
      const { data: { session } } = await supabase.auth.getSession();
      if (!session) throw new Error('No session');

      const response = await fetch(`${process.env.EXPO_PUBLIC_API_URL}/api/habits`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${session.access_token}`,
        },
        body: JSON.stringify(habitData),
      });

      if (!response.ok) throw new Error('Failed to create habit');
      const newHabit = await response.json();
      set((state) => ({
        habits: [...state.habits, newHabit],
        isLoading: false,
      }));
    } catch (err: any) {
      set({ error: err.message, isLoading: false });
    }
  },
}));

import { create } from 'zustand';
import api from '../../services/api_service';

export interface WeeklyInsightData {
  summary: {
    avgMood: number;
    avgEnergy: number;
    checkinCount: number;
    journalSessions: number;
    tasksCompleted: number;
    tasksTotal: number;
  };
  patterns: Array<{
    type: 'energy' | 'mood' | 'productivity' | 'sleep';
    description: string;
    confidence: 'high' | 'medium' | 'low';
  }>;
  recommendations: Array<{
    category: 'planning' | 'self-care' | 'social';
    text: string;
    priority: 'high' | 'medium' | 'low';
  }>;
