  sono:    { label: 'Sono',    color: '#9B7AB8', unit: 'h',   emoji: '😴' },
};

// Dados simulados — 7 dias
const MOCK_DATA: Record<Metric, number[]> = {
  humor:   [7, 6, 8, 5, 7, 9, 8],
  energia: [6, 5, 8, 4, 7, 8, 9],
  hrv:     [42, 38, 55, 30, 48, 62, 58],
